import{_ as d,o as a,c as e,ae as r}from"./chunks/framework.DQC_QtFV.js";const u=JSON.parse('{"title":"高级设置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console/advanced.md","filePath":"guide/console/advanced.md","lastUpdated":1793162416000}'),o={name:"guide/console/advanced.md"};function n(h,t,l,i,s,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="高级设置" tabindex="-1">高级设置 <a class="header-anchor" href="#高级设置" aria-label="Permalink to &quot;高级设置&quot;">​</a></h1><p>高级页是那些&quot;设完就不用再碰&quot;的数字和开关，六张卡片。</p><h2 id="读取范围" tabindex="-1">读取范围 <a class="header-anchor" href="#读取范围" aria-label="Permalink to &quot;读取范围&quot;">​</a></h2><p>驱动程序能读到哪些会话，是机器人允许列表的外层边界，由驱动强制执行。 两种：<strong>全部会话</strong>，或<strong>仅选中的会话</strong>（选哪些在 <a href="./conversations.html">会话</a> 的状态列里调）。 从 全部会话 切到 仅选中的会话 时，会用驱动今天在读的会话把选择种子好， 不会一步把整个镜像丢出范围。</p><h2 id="发送节奏" tabindex="-1">发送节奏 <a class="header-anchor" href="#发送节奏" aria-label="Permalink to &quot;发送节奏&quot;">​</a></h2><p>所有发送都经过驱动程序的队列，客户端无法绕过。一个会话超了字符预算就等窗口腾出空位。</p><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>含义</th></tr></thead><tbody><tr><td>最小间隔</td><td>—</td><td>两条操作之间至少隔多久（秒）</td></tr><tr><td>中文速度</td><td>—</td><td>一分钟打多少个中文字</td></tr><tr><td>其他字符速度</td><td>—</td><td>一分钟打多少个其他字符（英文、数字、表情）</td></tr><tr><td>图片和贴纸</td><td>—</td><td>一张图片或贴纸算多少个中文字</td></tr><tr><td>小黄脸</td><td>—</td><td>一个 QQ 表情算多少个中文字</td></tr><tr><td>统计窗口</td><td>—</td><td>按多长一段时间算一个会话的打字量；0 表示只看间隔</td></tr><tr><td>最长等待</td><td>—</td><td>一条发送最多等多久，超过就报错</td></tr></tbody></table><p><strong>保留默认节奏</strong>：自动化一个聊天客户端，行为和方法一样重要。</p><h2 id="合并消息" tabindex="-1">合并消息 <a class="header-anchor" href="#合并消息" aria-label="Permalink to &quot;合并消息&quot;">​</a></h2><p>一个会话里连来的消息攒多久再开一轮（秒）：</p><table tabindex="0"><thead><tr><th>项</th><th>默认</th><th>含义</th></tr></thead><tbody><tr><td>静默等待</td><td>2</td><td>没人再说话后，等多久再开轮次</td></tr><tr><td>轮次进行中</td><td>5</td><td>上一轮还没跑完时，等多久</td></tr><tr><td>同一人连续发</td><td>2</td><td>同一个人连发时，等多久</td></tr><tr><td>换人发</td><td>0.5</td><td>换成另一个人发时，等多久</td></tr><tr><td>被叫到的上限</td><td>1</td><td>叫到机器人时最多等多久</td></tr><tr><td>一批的上限</td><td>8</td><td>从这批第一条算起最多等多久</td></tr></tbody></table><h2 id="排队" tabindex="-1">排队 <a class="header-anchor" href="#排队" aria-label="Permalink to &quot;排队&quot;">​</a></h2><p>多个会话同时等的时候先回谁。</p><ul><li><strong>饿等上限</strong>（默认 120 秒）：等了这么久还没轮到的会话先回，和 Jev 怎么排无关。</li><li><strong>需要程度</strong>：Jev 按&quot;这个会话多需要现在被回复&quot;重排，阈值 0-2， 模式同样是 关闭 / 只记录不生效 / 启用，可加额外判断。</li></ul><h2 id="空闲轮" tabindex="-1">空闲轮 <a class="header-anchor" href="#空闲轮" aria-label="Permalink to &quot;空闲轮&quot;">​</a></h2><p>距上一轮开始过了这么久、而且一轮都没有时，机器人自己开一轮：这一轮不属于任何会话， 它可以做自己感兴趣的事（搜索、阅读、用工具、写笔记），也可以什么都不做。 默认 0（关）。任何一轮开始都会重新计时，空闲轮自己也算； 暂停、没有管理员、或正在跑一轮时不开。上限是一天。</p><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><p><code>code_exec</code> 把边角工具收进一个编码工具后面：模型写一段脚本来调用它们。 默认开启；关掉是模型不擅长 <code>code_exec</code> 时的退路。改动在下一个窗口生效。</p>',18)])])}const b=d(o,[["render",n]]);export{u as __pageData,b as default};
